query:
SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Cartesian product"@en "Zorn's lemma"@en "antichain"@en "antisymmetric"@en "axiom"@en "axiom of choice"@en "bijection"@en "bijective"@en "cardinality"@en "cartesian product"@en "chain"@en "codomain"@en "complement"@en "composition"@en "conclusion"@en "conjecture"@en "contradiction"@en "contrapositive"@en "converse"@en "corollary"@en "countable set"@en "counterexample"@en "definition"@en "domain"@en "empty set"@en "equivalence class"@en "equivalence relation"@en "extension"@en "finite set"@en "function"@en "greatest lower bound"@en "hypothesis"@en "identity function"@en "if and only if"@en "image"@en "implication"@en "infimum"@en "infinite set"@en "injection"@en "injective"@en "intersection"@en "inverse function"@en "least upper bound"@en "lemma"@en "lower bound"@en "mapping"@en "maximal element"@en "maximum"@en "minimal element"@en "minimum"@en "necessary condition"@en "ordered pair"@en "partial order"@en "poset"@en "power set"@en "preimage"@en "proof"@en "proof by contradiction"@en "proper subset"@en "proposition"@en "reflexive"@en "relation"@en "restriction"@en "set"@en "set difference"@en "singleton"@en "subset"@en "sufficient condition"@en "supremum"@en "surjection"@en "surjective"@en "symmetric"@en "symmetric difference"@en "theorem"@en "total order"@en "transitive"@en "tuple"@en "uncountable set"@en "union"@en "upper bound"@en "well-order"@en "zorn's lemma"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
